CREATE TABLE garments (id CHAR(36) PRIMARY KEY,item_code VARCHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,brand VARCHAR(100),style_code VARCHAR(100),color VARCHAR(100),size VARCHAR(100),material VARCHAR(100),description TEXT,care_instructions TEXT,image_url VARCHAR(2048),status ENUM('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',owner_phone VARCHAR(11),version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE tags (id CHAR(36) PRIMARY KEY,uid CHAR(14) COLLATE utf8mb4_bin NOT NULL UNIQUE,entry_code CHAR(32) COLLATE utf8mb4_bin NOT NULL UNIQUE,garment_id CHAR(36) UNIQUE,enabled BOOLEAN NOT NULL DEFAULT TRUE,write_verified_at DATETIME(3),notes VARCHAR(500),version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),FOREIGN KEY(garment_id) REFERENCES garments(id)) ENGINE=InnoDB;
CREATE TABLE admins (id CHAR(36) PRIMARY KEY,username VARCHAR(100) COLLATE utf8mb4_bin NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE admin_sessions (id CHAR(36) PRIMARY KEY,admin_id CHAR(36) NOT NULL,token_hash CHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE,expires_at DATETIME(3) NOT NULL,last_seen_at DATETIME(3) NOT NULL,FOREIGN KEY(admin_id) REFERENCES admins(id),INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id CHAR(36) PRIMARY KEY,admin_id CHAR(36) NOT NULL,action VARCHAR(50) NOT NULL,entity_type VARCHAR(30) NOT NULL,entity_id CHAR(36) NOT NULL,before_json JSON,after_json JSON,reason VARCHAR(200),request_id CHAR(36) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(admin_id) REFERENCES admins(id),INDEX(entity_type,entity_id,created_at)) ENGINE=InnoDB;
CREATE TABLE login_attempts (attempt_key CHAR(64) PRIMARY KEY,failures INT NOT NULL,window_start DATETIME(3) NOT NULL) ENGINE=InnoDB;
